import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: inter } = loadInter();



export type KnowledgeVsCapitalProps = Record<string, any>;

interface TextBlockProps {
  startFrame: number;
  endFrame: number;
  frame: number;
  content: React.ReactNode;
  isLast?: boolean;
}

const TextBlock: React.FC<TextBlockProps> = ({ startFrame, endFrame, frame, content, isLast }) => {
  const opacityIn = interpolate(frame, [startFrame, startFrame + 15], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const opacityOut = isLast
    ? 1
    : interpolate(frame, [endFrame - 15, endFrame], [1, 0], {
        extrapolateRight: "clamp",
        extrapolateLeft: "clamp",
      });
  const opacity = Math.min(opacityIn, opacityOut);
  const translateY = interpolate(frame, [startFrame, startFrame + 15], [20, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <div
      style={{
        opacity,
        transform: `translateY(${translateY}px)`,
        position: "absolute",
        width: "100%",
        textAlign: "center",
        fontFamily: inter,
        fontSize: 52,
        fontWeight: 500,
        lineHeight: 1.5,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {content}
    </div>
  );
};

const SvgGrid: React.FC<{ color: string }> = ({ color }) => (
  <svg width="100%" height="100%" style={{ position: "absolute", top: 0, left: 0, opacity: 0.1 }}>
    <defs>
      <pattern id="grid" width="80" height="80" patternUnits="userSpaceOnUse">
        <path d="M 80 0 L 0 0 0 80" fill="none" stroke={color} strokeWidth="1.5" />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#grid)" />
  </svg>
);

const KnowledgeVsCapital: React.FC<KnowledgeVsCapitalProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 10,
  knowledgeColor = "#06b6d4",
  capitalColor = "#10b981",
  textColor = "#f8fafc",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Dynamic Timings based on duration
  const totalFrames = durationInFrames;
  const shift1Frame = Math.floor(totalFrames * 0.15); 
  const shift2Frame = Math.floor(totalFrames * 0.48); 
  const shift3Frame = Math.floor(totalFrames * 0.81); 

  // Animation Springs
  const introPhase = spring({ frame, fps, config: { damping: 14 } });
  const shift1 = spring({ frame: frame - shift1Frame, fps, config: { damping: 14 } });
  const shift2 = spring({ frame: frame - shift2Frame, fps, config: { damping: 14 } });
  const shift3 = spring({ frame: frame - shift3Frame, fps, config: { damping: 14 } });

  // Calculate Values (Base 50/50 -> 90/10 -> 10/90 -> 50/50)
  const kValueRaw = (introPhase * 50) + (shift1 * 40) - (shift2 * 80) + (shift3 * 40);
  const cValueRaw = (introPhase * 50) - (shift1 * 40) + (shift2 * 80) - (shift3 * 40);
  
  // Clamp to prevent negative UI heights from spring bounce
  const kValue = Math.max(0.1, kValueRaw);
  const cValue = Math.max(0.1, cValueRaw);

  // Layout Calculations
  const barContainerTop = height * 0.45;
  const barContainerHeight = height * 0.35;
  const barWidth = width * 0.22;

  const leftCenterX = width * 0.28;
  const rightCenterX = width * 0.72;

  const kHeightPx = barContainerHeight * (kValue / 100);
  const cHeightPx = barContainerHeight * (cValue / 100);

  // SVG Line Coordinates
  const lineLeftY = barContainerHeight - kHeightPx;
  const lineRightY = barContainerHeight - cHeightPx;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <SvgGrid color={textColor} />

      {/* Dynamic Text Area */}
      <div style={{ position: "absolute", top: height * 0.15, left: 0, width: "100%", height: height * 0.25 }}>
        <TextBlock
          startFrame={shift1Frame}
          endFrame={shift2Frame - 15}
          frame={frame}
          content={
            <>
              <span style={{ color: textColor, display: "block" }}>
                The more <span style={{ color: knowledgeColor, fontFamily: spaceGrotesk, fontWeight: 700 }}>knowledge</span> you have,
              </span>
              <span style={{ color: textColor, display: "block", marginTop: 24 }}>
                the less <span style={{ color: capitalColor, fontFamily: spaceGrotesk, fontWeight: 700 }}>capital</span> you need.
              </span>
            </>
          }
        />
        
        <TextBlock
          startFrame={shift2Frame}
          endFrame={shift3Frame - 15}
          frame={frame}
          content={
            <>
              <span style={{ color: textColor, display: "block" }}>
                The more <span style={{ color: capitalColor, fontFamily: spaceGrotesk, fontWeight: 700 }}>capital</span> you have,
              </span>
              <span style={{ color: textColor, display: "block", marginTop: 24 }}>
                the less <span style={{ color: knowledgeColor, fontFamily: spaceGrotesk, fontWeight: 700 }}>knowledge</span> you need.
              </span>
            </>
          }
        />

        <TextBlock
          startFrame={shift3Frame}
          endFrame={totalFrames}
          frame={frame}
          isLast
          content={
            <>
              <span style={{ color: textColor, display: "block" }}>
                A perfect balance.
              </span>
              <span style={{ color: textColor, display: "block", marginTop: 24, fontSize: 40, opacity: 0.7 }}>
                The Inverse Relationship
              </span>
            </>
          }
        />
      </div>

      {/* Bars Visualization Area */}
      <div style={{ position: "absolute", top: barContainerTop, left: 0, width: "100%", height: barContainerHeight }}>
        
        {/* Seesaw Line */}
        <svg style={{ position: "absolute", top: 0, left: 0, width: width, height: barContainerHeight, overflow: "visible" }}>
          <line
            x1={leftCenterX}
            y1={lineLeftY}
            x2={rightCenterX}
            y2={lineRightY}
            stroke={textColor}
            strokeWidth={4}
            strokeDasharray="12 12"
            opacity={introPhase * 0.4}
          />
          <circle cx={leftCenterX} cy={lineLeftY} r={10} fill={knowledgeColor} opacity={introPhase} />
          <circle cx={rightCenterX} cy={lineRightY} r={10} fill={capitalColor} opacity={introPhase} />
          <circle cx={(leftCenterX + rightCenterX) / 2} cy={(lineLeftY + lineRightY) / 2} r={16} fill={textColor} opacity={introPhase} />
        </svg>

        {/* Knowledge Bar */}
        <div
          style={{
            position: "absolute",
            left: leftCenterX - barWidth / 2,
            bottom: 0,
            width: barWidth,
            height: kHeightPx,
            backgroundColor: knowledgeColor,
            borderTopLeftRadius: 20,
            borderTopRightRadius: 20,
            boxShadow: `0 0 60px ${knowledgeColor}40`,
            display: "flex",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              position: "absolute",
              top: -60,
              color: knowledgeColor,
              fontFamily: spaceGrotesk,
              fontWeight: 700,
              fontSize: 36,
              opacity: introPhase,
            }}
          >
            {Math.round(kValueRaw)}%
          </div>
        </div>

        {/* Capital Bar */}
        <div
          style={{
            position: "absolute",
            left: rightCenterX - barWidth / 2,
            bottom: 0,
            width: barWidth,
            height: cHeightPx,
            backgroundColor: capitalColor,
            borderTopLeftRadius: 20,
            borderTopRightRadius: 20,
            boxShadow: `0 0 60px ${capitalColor}40`,
            display: "flex",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              position: "absolute",
              top: -60,
              color: capitalColor,
              fontFamily: spaceGrotesk,
              fontWeight: 700,
              fontSize: 36,
              opacity: introPhase,
            }}
          >
            {Math.round(cValueRaw)}%
          </div>
        </div>
      </div>

      {/* Static Labels */}
      <div
        style={{
          position: "absolute",
          top: barContainerTop + barContainerHeight + 40,
          left: leftCenterX - barWidth,
          width: barWidth * 2,
          textAlign: "center",
          fontFamily: spaceGrotesk,
          fontWeight: 700,
          fontSize: 36,
          color: textColor,
          letterSpacing: 2,
          opacity: introPhase,
        }}
      >
        KNOWLEDGE
      </div>

      <div
        style={{
          position: "absolute",
          top: barContainerTop + barContainerHeight + 40,
          left: rightCenterX - barWidth,
          width: barWidth * 2,
          textAlign: "center",
          fontFamily: spaceGrotesk,
          fontWeight: 700,
          fontSize: 36,
          color: textColor,
          letterSpacing: 2,
          opacity: introPhase,
        }}
      >
        CAPITAL
      </div>
    </AbsoluteFill>
  );
};

export default KnowledgeVsCapital;